css:
.shiftsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2e22;
    background: linear-gradient(160deg, #f3f7ee 0%, #e8f1e2 100%);
    border-radius: 18px;
}

.shiftsim-container * {
    box-sizing: border-box;
}

.shiftsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1f5135 0%, #2f7a45 55%, #4ea35c 100%);
    color: #f4fbf0;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(31, 81, 53, 0.30);
}

.shiftsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.shiftsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #d7f0c8;
    background: rgba(255, 255, 255, 0.13);
    padding: 5px 14px;
    border-radius: 999px;
}

.shiftsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e4f4dc;
}

.shiftsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c5a3a;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.shiftsim-period-counter #currentDay,
.shiftsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1f5135;
}

.shiftsim-round-name {
    background: #d4ecc6;
    color: #1f5135;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.shiftsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4413;
    background: #fbe9d6;
    padding: 4px 12px;
    border-radius: 999px;
}

.shiftsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.shiftsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d9e8cf;
    box-shadow: 0 4px 14px rgba(31, 81, 53, 0.06);
    border-top: 4px solid #4ea35c;
}

.shiftsim-card-uptake { border-top-color: #2f7a45; }
.shiftsim-card-retention { border-top-color: #1d7d8c; }
.shiftsim-card-credibility { border-top-color: #b07d18; }
.shiftsim-card-cpc { border-top-color: #6a4fb0; }

.shiftsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5e7a64;
}

.shiftsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f5135;
}

.shiftsim-card-uptake .shiftsim-value { color: #2f7a45; }
.shiftsim-card-retention .shiftsim-value { color: #1d7d8c; }
.shiftsim-card-credibility .shiftsim-value { color: #b07d18; }
.shiftsim-card-cpc .shiftsim-value { color: #6a4fb0; }

.shiftsim-sublabel {
    font-size: 0.74rem;
    color: #708d76;
    line-height: 1.35;
}

.shiftsim-uptake-target .shiftsim-value { color: #2f7a45; }
.shiftsim-uptake-fail .shiftsim-value { color: #c0392b; }

.shiftsim-credibility-greenwash { border-top-color: #c0392b; }
.shiftsim-credibility-greenwash .shiftsim-value { color: #c0392b; }

.shiftsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1f5135;
    color: #eef8e8;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.shiftsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.shiftsim-budget-over #budgetDisplay {
    color: #ffb3a1;
}

.shiftsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #4ea35c;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(31, 81, 53, 0.05);
}

.shiftsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.shiftsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f5135;
    margin-bottom: 6px;
}

.shiftsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #314639;
}

.shiftsim-briefing-text strong { color: #2f7a45; }
.shiftsim-briefing-text em { color: #9a4413; font-style: italic; }

.shiftsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d9e8cf;
    box-shadow: 0 4px 14px rgba(31, 81, 53, 0.06);
}

.shiftsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f5135;
    border-bottom: 2px solid #e6f0de;
    padding-bottom: 8px;
}

.shiftsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #28412f;
    margin: 14px 0 6px;
}

.shiftsim-container select,
.shiftsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcd6ab;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7fcf3;
    color: #1f2e22;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.shiftsim-container select:focus,
.shiftsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2f7a45;
    box-shadow: 0 0 0 3px rgba(47, 122, 69, 0.15);
}

.shiftsim-container select option {
    background-color: #ffffff;
    color: #1f2e22;
}

.shiftsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f7a45;
}

.shiftsim-range-readout,
.shiftsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2c5a3a;
    margin-top: 4px;
}

.shiftsim-range-readout span:last-child,
.shiftsim-alloc-readout span:nth-child(2) {
    color: #2f7a45;
    font-weight: 800;
}

.shiftsim-hint {
    font-size: 0.8rem;
    color: #708d76;
    margin-top: 4px;
    line-height: 1.4;
}

.shiftsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.shiftsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f3f9ec;
    border: 1px solid #dceacf;
    border-radius: 9px;
    padding: 8px 12px;
}

.shiftsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #28412f;
}

.shiftsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.shiftsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.shiftsim-container .btn-primary {
    background: linear-gradient(135deg, #2f7a45 0%, #4ea35c 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(47, 122, 69, 0.28);
}

.shiftsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.shiftsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcd6ab;
    color: #5e7a64;
}

.shiftsim-coach {
    background: #1f5135;
    color: #eef8e8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(31, 81, 53, 0.22);
}

.shiftsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #9bd6a3;
    margin-bottom: 8px;
}

.shiftsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.shiftsim-coach-body strong { color: #ffe09a; }
.shiftsim-coach-body em { color: #ffc1ad; font-style: italic; }

.shiftsim-history,
.shiftsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d9e8cf;
    box-shadow: 0 4px 14px rgba(31, 81, 53, 0.06);
}

.shiftsim-history h3,
.shiftsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f5135;
}

.shiftsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #28412f;
}

.shiftsim-container table#usfHistoryTable th {
    background: #eaf4e2;
    color: #1f5135;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4e8c6;
}

.shiftsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef5e8;
}

.shiftsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fcf4;
}

.shiftsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .shiftsim-container {
        padding: 14px;
    }
    .shiftsim-header h1 {
        font-size: 1.7rem;
    }
    .shiftsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .shiftsim-value {
        font-size: 2rem;
    }
    .shiftsim-clock {
        margin-left: 0;
    }
    .shiftsim-period-counter {
        font-size: 0.88rem;
    }
    .shiftsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .shiftsim-alloc-row {
        flex-wrap: wrap;
    }
    .shiftsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .shiftsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ── v1.1.0: completion debrief card (append-only, self-contained) ── */
.shift-cm { font-family: inherit; color: #1f2e22; padding: 4px 2px 2px; }
.shift-cm-scoreblock { text-align: center; padding: 14px 12px 16px; background: linear-gradient(160deg,#f3f7ee,#e8f1e2); border-radius: 14px; border: 1px solid #d9e8cf; }
.shift-cm-scorenum { font-size: 3.1rem; font-weight: 800; line-height: 1; color: #1f5135; }
.shift-cm-scoremax { font-size: 1.15rem; font-weight: 600; color: #6a836f; margin-left: 2px; }
.shift-cm-scorelabel { font-size: .72rem; letter-spacing: .08em; text-transform: uppercase; color: #6a836f; margin-top: 6px; }
.shift-cm-grade { font-size: 1.16rem; font-weight: 700; color: #2c5a3a; margin-top: 8px; }
.shift-cm-badge { display: inline-block; margin-top: 10px; padding: 4px 14px; border-radius: 999px; font-size: .78rem; font-weight: 700; }
.shift-cm-badge-pass { background: #d4ecc6; color: #1f5135; }
.shift-cm-badge-miss { background: #ffe0d6; color: #b0361c; }
.shift-cm-kpis { display: grid; grid-template-columns: repeat(4,1fr); gap: 10px; margin: 16px 0 4px; }
.shift-cm-kpi { background: #ffffff; border: 1px solid #e4ede0; border-top: 3px solid #2f7a45; border-radius: 10px; padding: 12px 8px; text-align: center; }
.shift-cm-k-uptake { border-top-color: #2f7a45; }
.shift-cm-k-retention { border-top-color: #1d7d8c; }
.shift-cm-k-cred { border-top-color: #b07d18; }
.shift-cm-k-cpc { border-top-color: #6a4fb0; }
.shift-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #1f2e22; line-height: 1.05; }
.shift-cm-k-uptake .shift-cm-kpi-val { color: #2f7a45; }
.shift-cm-k-retention .shift-cm-kpi-val { color: #1d7d8c; }
.shift-cm-k-cred .shift-cm-kpi-val { color: #b07d18; }
.shift-cm-k-cpc .shift-cm-kpi-val { color: #6a4fb0; }
.shift-cm-kpi-label { font-size: .74rem; font-weight: 700; color: #3c4a40; margin-top: 5px; }
.shift-cm-kpi-sub { font-size: .64rem; color: #8a978d; margin-top: 2px; line-height: 1.25; }
.shift-cm-insights { margin: 16px 2px 6px; }
.shift-cm-insights h6 { font-size: .74rem; letter-spacing: .06em; text-transform: uppercase; color: #6a836f; margin: 0 0 8px; font-weight: 700; }
.shift-cm-insights ul { margin: 0; padding-left: 18px; }
.shift-cm-insights li { font-size: .86rem; line-height: 1.5; color: #2b3a30; margin-bottom: 7px; }
.shift-cm-footer { margin-top: 14px; padding-top: 10px; border-top: 1px solid #e4ede0; font-size: .72rem; color: #8a978d; text-align: center; font-style: italic; }
@media (max-width: 640px) { .shift-cm-kpis { grid-template-columns: repeat(2,1fr); } .shift-cm-scorenum { font-size: 2.6rem; } }

